"""Reuse original100g protocol and actual response provenance;no state edits."""
import argparse,csv,json,xml.etree.ElementTree as ET
from pathlib import Path
import numpy as np
from analyse import BASE,sha
def read(f):return list(csv.DictReader(f.open()))
def main():
 p=argparse.ArgumentParser();p.add_argument('--tag',required=True);p.add_argument('--case',default='b3_railback_grasp1001298');a=p.parse_args();src=BASE/'results'/a.case;out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);run=json.loads((src/'summary.json').read_text());protocol_src=BASE/'results/b3_mass100_explore1059/holding_protocol.json';protocol=json.loads(protocol_src.read_text());rows=read(src/'object.csv');t=np.array([float(r['time_s']) for r in rows]);index={x:i for i,x in enumerate(t)};q=np.array([np.fromstring(r['rigid_q'],sep=' ') for r in rows]);v=np.array([np.fromstring(r['rigid_v'],sep=' ') for r in rows]);total=np.array([np.fromstring(r['object_impulse_Ns_Nms'],sep=' ') for r in rows]);names=('skin','rail','guide','support','other');parts={n:np.zeros_like(total) for n in names};seen=set()
 for r in read(src/'response_rows.csv'):
  paths=(r['model0'],r['model1'])
  if not any('/object/'in x for x in paths):continue
  time=float(r['time_s']);key=(time,int(r['row_id']));assert key not in seen;seen.add(key);other=paths[1] if '/object/'in paths[0] else paths[0];name='skin' if '/skinCollision/'in other else 'rail' if '/railCollision/'in other else 'guide' if '/guides'in other else 'support' if '/floor/'in other else 'other';parts[name][index[time]]+=np.fromstring(r['object_impulse_Ns_Nms'],sep=' ')
 dt=.0025;window=(t>=1.6-1e-12)&(t<=2+1e-12);assert window.any() and len(t)==800,'full2s protocol required';ref=int(np.argmin(abs(t-protocol['reference_s'])));tree=ET.parse(src/'scene.scn');R=float(tree.find("./Node[@name='object']/Node/SphereCollisionModel").get('radius'));supportR=float(tree.find("./Node[@name='floor']/SphereCollisionModel").get('radius'));supp=read(src/'support.csv');assert [float(r['time_s']) for r in supp]==t.tolist();sq=np.array([np.fromstring(r['q'],sep=' ') for r in supp]);gap=np.linalg.norm(q[:,:3]-sq,axis=1)-R-supportR;slip=float((q[ref,2]-q[window,2]).max()*1000);speed=float(np.linalg.norm(v[window,:3],axis=1).max()*1000);support=float(np.linalg.norm(parts['support'][window,:3]/dt,axis=1).max());error=float(abs(total-sum(parts.values())).max());tests=dict(slip=slip<=protocol['max_vertical_slip_mm'],speed=speed<=protocol['max_speed_mm_s'],clearance=float(gap[window].min()*1000)>=protocol['minimum_support_surface_gap_mm'],support=support<=protocol['maximum_support_resultant_N'],partition=error<=1e-12,valid_saved_elements=run['status']=='VALID_BOUNDED_EXPLORATION_ONLY');tests={k:bool(v) for k,v in tests.items()};forces={n:dict(mean_force_N=(p[window,:3]/dt).mean(axis=0).tolist(),maximum_resultant_force_N=float(np.linalg.norm(p[window,:3]/dt,axis=1).max())) for n,p in parts.items()};d=dict(status='EXPLORATORY_FUNCTIONAL_HOLD_ONLY' if all(tests.values()) else 'FAIL_EXPLORATORY_HOLD',tests=tests,case=a.case,holding_protocol=protocol,holding_protocol_source_sha256=sha(protocol_src),protocol_note='Original user100g protocol,not retroactively fitted thresholds;Native row source and physics gates unchanged',hold_outputs=int(window.sum()),slip_mm=slip,max_speed_mm_s=speed,minimum_support_surface_gap_mm=float(gap[window].min()*1000),maximum_support_force_N=support,response_partition_max_error_Ns_Nms=error,forces=forces,max_hold_solver_iterations=max(int(r['solver_iterations']) for r,w in zip(rows,window) if w),source_quality=run['qualities'],physical_validation='NOT QUALIFIED',hardware_joint='IDEAL_ASSUMPTION',whole_energy=None,input_hashes={f:sha(src/f) for f in ('scene.scn','object.csv','support.csv','response_rows.csv','summary.json')});(out/'producer.py').write_bytes(Path(__file__).read_bytes());(out/'summary.json').write_text(json.dumps(d,indent=2));print(json.dumps(d))
if __name__=='__main__':main()
